267	    fn is_path_ignored(&self, params: IsPathIgnoredParams) -> Result<bool, WorkspaceError> {
268	        let settings = self.settings();
269	        let path = params.rome_path.as_path();
270	        if path.file_name().and_then(|s| s.to_str()) == Some(BIOME_JSON) {
271	            return Ok(false);
272	        }
273	
274	        // The top-level `files.include`/`files.ignore` and the VCS ignore file
275	        // (e.g. `.gitignore`) always take precedence over any feature-level
276	        // include/ignore list. A file excluded here can never be processed,
277	        // even if a feature-level `include` matches it.
278	        //
279	        // Note: override-level `ignore`/`include` patterns are intentionally
280	        // *not* consulted here. They only affect the settings applied by their
281	        // own override and must not influence whether a file is processed at
282	        // all.
283	        if self.is_ignored_by_top_level_config(path) {
284	            return Ok(true);
285	        }
286	
287	        let (ignored_files, included_files) = match params.feature {
288	            FeatureName::Format => {
289	                let formatter = &settings.as_ref().formatter;
290	                (&formatter.ignored_files, &formatter.included_files)
291	            }
292	            FeatureName::Lint => {
293	                let linter = &settings.as_ref().linter;
294	                (&linter.ignored_files, &linter.included_files)
295	            }
296	            FeatureName::OrganizeImports => {
297	                let organize_imports = &settings.as_ref().organize_imports;
298	                (
299	                    &organize_imports.ignored_files,
300	                    &organize_imports.included_files,
301	                )
302	            }
303	        };
304	
305	        // Only files that passed the higher-priority global/VCS filters above
306	        // are subject to feature-level include/ignore filtering.
307	        if ignored_files.matches_path(path) {
308	            return Ok(true);
309	        }
310	        if !included_files.is_empty() && !included_files.matches_path(path) {
311	            return Ok(true);
312	        }
313	
314	        Ok(false)
315	    }
