path(path) {\n            return Ok(true);\n        }\n        if !included_files.is_empty() && !included_files.matches_path(path) {\n            return Ok(true);\n        }\n\n        Ok(false)", "numLines": 48, "startLine": 267, "totalLines": 645}}
